/**
 * The workspace write lock: which subscription states make an organization
 * read-only, and the error a refused write raises.
 *
 * Pure apart from the clock. `assertWorkspaceWritable()` in the billing service
 * reads the stored subscription and asks `lockReasonFor()` here; nothing else
 * decides the lock.
 */
import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

/** Raised by a write service when the workspace is locked at the moment of the write. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(
      `Workspace ${orgId} is read-only while its billing is not in good standing (${reason})`,
    );
    this.name = "WorkspaceLockedError";
  }
}

/**
 * The lock rule, evaluated at `now` against the subscription as stored.
 *
 * - no subscription row, or `active`: writable
 * - `past_due`: locked
 * - `trialing`: locked from the moment the period end is reached
 * - `canceled`: locked from the moment the cancellation date is reached; a
 *   cancellation scheduled for later keeps the workspace writable until then,
 *   and a canceled subscription with no cancellation date is locked now
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return reached(subscription.currentPeriodEnd, now) ? "trial_ended" : null;
    case "canceled":
      return subscription.cancelAt === null || reached(subscription.cancelAt, now)
        ? "canceled"
        : null;
  }
}

function reached(at: string, now: Date): boolean {
  return new Date(at).getTime() <= now.getTime();
}

