const { toAppError, isDomainError } = await import(`${PROJECT}/src/lib/errors.ts`);

const sub = (status: string, extra: Record<string, unknown> = {}) => ({
  id: "s", orgId: "o", plan: "growth", interval: "monthly", seats: 1,
  currentPeriodStart: "2026-01-01T00:00:00.000Z",
  currentPeriodEnd: "2026-02-01T00:00:00.000Z",
  cancelAt: null, createdAt: "2026-01-01T00:00:00.000Z", updatedAt: "2026-01-01T00:00:00.000Z",
  status, ...extra,
});
const at = (iso: string) => new Date(iso);
const cases: [string, unknown, unknown][] = [
  ["no row", lockReasonFor(null, at("2026-03-01T00:00:00.000Z")), null],
  ["active", lockReasonFor(sub("active"), at("2026-03-01T00:00:00.000Z")), null],
  ["past_due", lockReasonFor(sub("past_due"), at("2026-01-02T00:00:00.000Z")), "past_due"],
  ["trialing before end", lockReasonFor(sub("trialing"), at("2026-01-31T23:59:59.000Z")), null],
  ["trialing at end", lockReasonFor(sub("trialing"), at("2026-02-01T00:00:00.000Z")), "trial_ended"],
  ["canceled no date", lockReasonFor(sub("canceled"), at("2026-01-02T00:00:00.000Z")), "canceled"],
