const t = await createTenant("lockcheck", "growth");
const setStatus = (status: string) =>
  getDb().update(subscriptions).set({ status: status as never }).where(eq(subscriptions.orgId, t.org.id)).run();

const tryWrite = async (label: string, fn: () => Promise<unknown>) => {
  try { await fn(); console.log("WRITE OK  ", label); }
  catch (e) { console.log("WRITE ERR ", label, toAppError(e).code, (e as Error).name); }
};

await tryWrite("create issue (trialing, in trial)", () => issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id)));
setStatus("past_due");
await tryWrite("create issue (past_due)", () => issueService.createIssue(t.actors.owner, issueInput(t.org.id, t.project.id)));
await tryWrite("create issue as viewer (past_due, wrong role -> forbidden expected)", () => issueService.createIssue(t.actors.viewer, issueInput(t.org.id, t.project.id)));
console.log("summary lockReason:", (await import(`${PROJECT}/src/server/services/organization-service.ts`)).getOrganizationSummary);
await tryWrite("assertWorkspaceWritable (past_due)", () => billingService.assertWorkspaceWritable(t.org.id));
await tryWrite("changePlan growth->starter (unlocks)", () => billingService.changePlan(t.actors.owner, { orgId: t.org.id, plan: "growth", interval: "monthly" } as never));
await tryWrite("assertWorkspaceWritable after plan change", () => billingService.assertWorkspaceWritable(t.org.id));
await tryWrite("invite (active)", () => invitationService.inviteMembers(t.actors.owner, { orgId: t.org.id, invites: [{ email: "new@x.test", role: "viewer" }] } as never));

console.log("FAILED CASES:", failed);
